-- Generated by scripts/build-collection-model.mjs. JSON is never stored in columns.
-- Named business tables are kept atomic with the lossless typed compatibility data.
LOCK TABLE epav_data.records IN SHARE ROW EXCLUSIVE MODE;

CREATE FUNCTION epav_data.field_node(rid bigint,parts varchar[]) RETURNS integer
LANGUAGE plpgsql STABLE SET search_path=pg_catalog,epav_data AS $$
DECLARE parent integer; part varchar;
BEGIN
  FOREACH part IN ARRAY parts LOOP
    SELECT node_no INTO parent FROM epav_data.record_fields
      WHERE document_row_id=rid AND parent_no IS NOT DISTINCT FROM parent AND field_name=part;
    IF parent IS NULL THEN RETURN NULL; END IF;
  END LOOP;
  RETURN parent;
END $$;
CREATE FUNCTION epav_data.field_value(rid bigint,parts varchar[]) RETURNS varchar
LANGUAGE sql STABLE SET search_path=pg_catalog,epav_data AS $$
  SELECT coalesce(string_value,integer_value::varchar,double_value::varchar,boolean_value::varchar,
    to_char(timestamp_value AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"'))
  FROM epav_data.record_fields WHERE document_row_id=rid AND node_no=epav_data.field_node(rid,parts)
$$;
CREATE FUNCTION epav_data.field_string(rid bigint,parts varchar[]) RETURNS varchar
LANGUAGE sql STABLE SET search_path=pg_catalog,epav_data AS $$
  SELECT string_value FROM epav_data.record_fields WHERE document_row_id=rid AND node_no=epav_data.field_node(rid,parts)
$$;
CREATE FUNCTION epav_data.field_number(rid bigint,parts varchar[]) RETURNS double precision
LANGUAGE sql STABLE SET search_path=pg_catalog,epav_data AS $$
  SELECT coalesce(double_value,integer_value::double precision) FROM epav_data.record_fields
    WHERE document_row_id=rid AND node_no=epav_data.field_node(rid,parts)
$$;
CREATE FUNCTION epav_data.field_strings(rid bigint,parts varchar[]) RETURNS varchar[]
LANGUAGE sql STABLE SET search_path=pg_catalog,epav_data AS $$
  SELECT ARRAY(SELECT string_value::varchar(240) FROM epav_data.record_fields
    WHERE document_row_id=rid AND parent_no=epav_data.field_node(rid,parts) ORDER BY array_index)
$$;

CREATE TABLE epav_data.importacoes_catalogo(
  id varchar(1500) PRIMARY KEY,
  registro_id bigint NOT NULL UNIQUE REFERENCES epav_data.records(row_id) ON DELETE CASCADE,
