,'Churrasco']::varchar[])::varchar(3),epav_data.field_value(rid,prefix||ARRAY['dadosOriginais','Lanches']::varchar[])::varchar(3),epav_data.field_value(rid,prefix||ARRAY['dadosOriginais','Receitas']::varchar[])::varchar(3),epav_data.field_value(rid,prefix||ARRAY['dadosOriginais','Família']::varchar[])::varchar(3),epav_data.field_value(rid,prefix||ARRAY['dadosOriginais','Ocasiões especiais']::varchar[])::varchar(3),epav_data.field_value(rid,prefix||ARRAY['dadosOriginais','Leve']::varchar[])::varchar(3))
    ON CONFLICT(versao_id) DO UPDATE SET codigo_produto=excluded.codigo_produto,descricao_produto=excluded.descricao_produto,unidade_medida=excluded.unidade_medida,volume_kg=excluded.volume_kg,volume_un=excluded.volume_un,preco_medio_sem_desconto=excluded.preco_medio_sem_desconto,preco_sem_desconto_observacao=excluded.preco_sem_desconto_observacao,preco_medio_com_desconto=excluded.preco_medio_com_desconto,preco_com_desconto_observacao=excluded.preco_com_desconto_observacao,margem_contribuicao=excluded.margem_contribuicao,margem_observacao=excluded.margem_observacao,status_produto=excluded.status_produto,familia=excluded.familia,marca=excluded.marca,familia_analitica_1=excluded.familia_analitica_1,familia_analitica_2=excluded.familia_analitica_2,nome_fornecedor=excluded.nome_fornecedor,ocasiao=excluded.ocasiao,formato=excluded.formato,produtor=excluded.produtor,categoria=excluded.categoria,valor_agregado=excluded.valor_agregado,tipo_produto_original=excluded.tipo_produto_original,disponivel_original=excluded.disponivel_original,ocasioes_original=excluded.ocasioes_original,carnes=excluded.carnes,aves=excluded.aves,pescados=excluded.pescados,acompanhamentos=excluded.acompanhamentos,sobremesas=excluded.sobremesas,despensa=excluded.despensa,praticidade=excluded.praticidade,dia_a_dia=excluded.dia_a_dia,churrasco=excluded.churrasco,lanches=excluded.lanches,receitas=excluded.receitas,familia_ocasiao=excluded.familia_ocasiao,ocasioes_especiais=excluded.ocasioes_especiais,leve=excluded.leve;
    IF epav_data.field_node(rid,prefix||ARRAY['imagemSwift']::varchar[]) IS NULL THEN
      DELETE FROM epav_data.versoes_produtos_imagens WHERE versao_id=vid;
    ELSE
      INSERT INTO epav_data.versoes_produtos_imagens(versao_id,bucket,object_key,url,formato,largura,altura,bytes,sha256,pixel_hash,nome_origem,pagina_origem,sku_origem,url_origem,metodo_correspondencia,versao_correspondencia,versao_transformacao,manual,origem,atualizado_em) VALUES(vid,epav_data.field_value(rid,prefix||ARRAY['imagemSwift','bucket']::varchar[])::varchar(120),epav_data.field_value(rid,prefix||ARRAY['imagemSwift','key']::varchar[])::varchar(1024),epav_data.field_value(rid,prefix||ARRAY['imagemSwift','url']::varchar[])::varchar(4096),epav_data.field_value(rid,prefix||ARRAY['imagemSwift','format']::varchar[])::varchar(20),epav_data.field_number(rid,prefix||ARRAY['imagemSwift','width']::varchar[])::integer,epav_data.field_number(rid,prefix||ARRAY['imagemSwift','height']::varchar[])::integer,epav_data.field_number(rid,prefix||ARRAY['imagemSwift','bytes']::varchar[])::bigint,epav_data.field_value(rid,prefix||ARRAY['imagemSwift','sha256']::varchar[])::varchar(64),epav_data.field_value(rid,prefix||ARRAY['imagemSwift','pixelHash']::varchar[])::varchar(64),epav_data.field_value(rid,prefix||ARRAY['imagemSwift','sourceName']::varchar[])::varchar(240),epav_data.field_value(rid,prefix||ARRAY['imagemSwift','sourcePage']::varchar[])::varchar(4096),epav_data.field_value(rid,prefix||ARRAY['imagemSwift','sourceSku']::varchar[])::varchar(128),epav_data.field_value(rid,prefix||ARRAY['imagemSwift','sourceUrl']::varchar[])::varchar(4096),epav_data.field_value(rid,prefix||ARRAY['imagemSwift','matchMethod']::varchar[])::varchar(80),epav_data.field_value(rid,prefix||ARRAY['imagemSwift','matchVersion']::varchar[])::varchar(80),epav_data.field_value(rid,prefix||ARRAY['imagemSwift','transformVersion']::varchar[])::varchar(80),epav_data.field_value(rid,prefix||ARRAY['imagemSwift','manual']::varchar[])::boolean,epav_data.field_value(rid,prefix||ARRAY['imagemSwift','source']::varchar[])::varchar(80),epav_data.field_value(rid,prefix||ARRAY['imagemSwift','updatedAt']::varchar[])::timestamptz)
    ON CONFLICT(versao_id) DO UPDATE SET bucket=excluded.bucket,object_key=excluded.object_key,url=excluded.url,formato=excluded.formato,largura=excluded.largura,altura=excluded.altura,bytes=excluded.bytes,sha256=excluded.sha256,pixel_hash=excluded.pixel_hash,nome_origem=excluded.nome_origem,pagina_origem=excluded.pagina_origem,sku_origem=excluded.sku_origem,url_origem=excluded.url_origem,metodo_correspondencia=excluded.metodo_correspondencia,versao_correspondencia=excluded.versao_correspondencia,versao_transformacao=excluded.versao_transformacao,manual=excluded.manual,origem=excluded.origem,atualizado_em=excluded.atualizado_em;
    END IF;
  END IF;
END $$;
CREATE FUNCTION epav_data.refresh_product_version(rid bigint,pos varchar) RETURNS bigint
LANGUAGE plpgsql SET search_path=pg_catalog,epav_data AS $$
DECLARE vid bigint;
BEGIN
  INSERT INTO epav_data.produtos_swift_versoes(registro_id,posicao,produto_origem_id,codigo,nome,disponivel_no_jogo,importacao_id,linha_origem,tipos_produto,ocasioes,atualizado_em,atualizado_por,ultima_alteracao_id) VALUES(rid,pos,epav_data.field_value(rid,ARRAY[pos,'id']::varchar[]),epav_data.field_value(rid,ARRAY[pos,'codigo']::varchar[])::varchar(128),epav_data.field_value(rid,ARRAY[pos,'nome']::varchar[])::varchar(240),epav_data.field_value(rid,ARRAY[pos,'disponivelNoJogo']::varchar[])::boolean,epav_data.field_value(rid,ARRAY[pos,'importacaoId']::varchar[])::varchar(1500),epav_data.field_number(rid,ARRAY[pos,'linhaOrigem']::varchar[])::integer,epav_data.field_strings(rid,ARRAY[pos,'tiposProduto']::varchar[]),epav_data.field_strings(rid,ARRAY[pos,'ocasioes']::varchar[]),epav_data.field_value(rid,ARRAY[pos,'atualizadoEm']::varchar[])::timestamptz,epav_data.field_value(rid,ARRAY[pos,'atualizadoPor']::varchar[])::varchar(128),epav_data.field_value(rid,ARRAY[pos,'ultimaAlteracaoId']::varchar[])::varchar(128))
    ON CONFLICT(registro_id,posicao) DO UPDATE SET produto_origem_id=excluded.produto_origem_id,codigo=excluded.codigo,nome=excluded.nome,disponivel_no_jogo=excluded.disponivel_no_jogo,importacao_id=excluded.importacao_id,linha_origem=excluded.linha_origem,tipos_produto=excluded.tipos_produto,ocasioes=excluded.ocasioes,atualizado_em=excluded.atualizado_em,atualizado_por=excluded.atualizado_por,ultima_alteracao_id=excluded.ultima_alteracao_id
    RETURNING id INTO vid;
  PERFORM epav_data.refresh_product_children(rid,ARRAY[pos]::varchar[],NULL,vid);
  RETURN vid;
END $$;
CREATE FUNCTION epav_data.refresh_business_record(rid bigint) RETURNS void
LANGUAGE plpgsql SET search_path=pg_catalog,epav_data AS $$
DECLARE r epav_data.records; vid bigint; before_id bigint; after_id bigint; current_id varchar;
BEGIN
  SELECT * INTO r FROM epav_data.records WHERE row_id=rid;
  IF NOT FOUND THEN RETURN; END IF;
  IF r.collection_path='importacoes_catalogo' THEN
    INSERT INTO epav_data.importacoes_catalogo(id,registro_id,arquivo_origem,aba_origem,colecao_origem,projeto_firebase_origem,importacao_origem_id,schema_version,sha256_origem,status,total_disponiveis,total_registros,verificado_em,campos_originais) VALUES(r.document_id,rid,epav_data.field_value(rid,ARRAY['arquivoOrigem']::varchar[]),epav_data.field_value(rid,ARRAY['abaOrigem']::varchar[]),epav_data.field_value(rid,ARRAY['colecao']::varchar[]),epav_data.field_value(rid,ARRAY['projetoFirebase']::varchar[]),epav_data.field_value(rid,ARRAY['importacaoId']::varchar[]),epav_data.field_value(rid,ARRAY['schemaVersion']::varchar[])::integer,epav_data.field_value(rid,ARRAY['sha256Origem']::varchar[]),epav_data.field_value(rid,ARRAY['status']::varchar[]),epav_data.field_value(rid,ARRAY['totalDisponiveis']::varchar[])::integer,epav_data.field_value(rid,ARRAY['totalRegistros']::varchar[])::integer,epav_data.field_value(rid,ARRAY['verificadoEm']::varchar[])::timestamptz,epav_data.field_strings(rid,ARRAY['camposOriginais']::varchar[]))
    ON CONFLICT(id) DO UPDATE SET registro_id=excluded.registro_id,arquivo_origem=excluded.arquivo_origem,aba_origem=excluded.aba_origem,colecao_origem=excluded.colecao_origem,projeto_firebase_origem=excluded.projeto_firebase_origem,importacao_origem_id=excluded.importacao_origem_id,schema_version=excluded.schema_version,sha256_origem=excluded.sha256_origem,status=excluded.status,total_disponiveis=excluded.total_disponiveis,total_registros=excluded.total_registros,verificado_em=excluded.verificado_em,campos_originais=excluded.campos_originais;
  ELSIF r.collection_path='produtos_swift' THEN
    INSERT INTO epav_data.produtos_swift(id,registro_id,codigo,nome,disponivel_no_jogo,importacao_id,linha_origem,tipos_produto,ocasioes,atualizado_em,atualizado_por,ultima_alteracao_id) VALUES(r.document_id,rid,epav_data.field_value(rid,ARRAY['codigo']::varchar[])::varchar(128),epav_data.field_value(rid,ARRAY['nome']::varchar[])::varchar(240),epav_data.field_value(rid,ARRAY['disponivelNoJogo']::varchar[])::boolean,epav_data.field_value(rid,ARRAY['importacaoId']::varchar[])::varchar(1500),epav_data.field_number(rid,ARRAY['linhaOrigem']::varchar[])::integer,epav_data.field_strings(rid,ARRAY['tiposProduto']::varchar[]),epav_data.field_strings(rid,ARRAY['ocasioes']::varchar[]),epav_data.field_value(rid,ARRAY['atualizadoEm']::varchar[])::timestamptz,epav_data.field_value(rid,ARRAY['atualizadoPor']::varchar[])::varchar(128),epav_data.field_value(rid,ARRAY['ultimaAlteracaoId']::varchar[])::varchar(128))
    ON CONFLICT(id) DO UPDATE SET registro_id=excluded.registro_id,codigo=excluded.codigo,nome=excluded.nome,disponivel_no_jogo=excluded.disponivel_no_jogo,importacao_id=excluded.importacao_id,linha_origem=excluded.linha_origem,tipos_produto=excluded.tipos_produto,ocasioes=excluded.ocasioes,atualizado_em=excluded.atualizado_em,atualizado_por=excluded.atualizado_por,ultima_alteracao_id=excluded.ultima_alteracao_id;
    PERFORM epav_data.refresh_product_children(rid,ARRAY[]::varchar[],r.document_id,NULL);
    UPDATE epav_data.sincronizacao_imagens_swift SET produto_atual_id=r.document_id WHERE produto_origem_id=r.document_id AND produto_atual_id IS NULL;
    UPDATE epav_data.auditoria_catalogo SET produto_atual_id=r.document_id WHERE produto_origem_id=r.document_id AND produto_atual_id IS NULL;
  ELSIF r.collection_path='arquivo_produtos_swift' THEN
    vid:=epav_data.refresh_product_version(rid,'dados');
    INSERT INTO epav_data.arquivo_produtos_swift(id,registro_id,produto_origem_id,motivo,versao_original,duplicado_de,arquivado_em,dados_versao_id) VALUES(r.document_id,rid,epav_data.field_value(rid,ARRAY['produtoId']::varchar[]),epav_data.field_value(rid,ARRAY['motivo']::varchar[]),epav_data.field_value(rid,ARRAY['versaoOriginal']::varchar[]),epav_data.field_value(rid,ARRAY['duplicadoDe']::varchar[]),epav_data.field_value(rid,ARRAY['arquivadoEm']::varchar[])::timestamptz,vid)
    ON CONFLICT(id) DO UPDATE SET registro_id=excluded.registro_id,produto_origem_id=excluded.produto_origem_id,motivo=excluded.motivo,versao_original=excluded.versao_original,duplicado_de=excluded.duplicado_de,arquivado_em=excluded.arquivado_em,dados_versao_id=excluded.dados_versao_id;
  ELSIF r.collection_path='auditoria_catalogo' THEN
    before_id:=epav_data.refresh_product_version(rid,'antes');
    after_id:=epav_data.refresh_product_version(rid,'depois');
    SELECT id INTO current_id FROM epav_data.produtos_swift WHERE id=epav_data.field_value(rid,ARRAY['produtoId']::varchar[]);
    INSERT INTO epav_data.auditoria_catalogo(id,registro_id,produto_origem_id,produto_atual_id,autor_uid,autor_email,criado_em,antes_versao_id,depois_versao_id) VALUES(r.document_id,rid,epav_data.field_value(rid,ARRAY['produtoId']::varchar[]),current_id,epav_data.field_value(rid,ARRAY['autorUid']::varchar[]),epav_data.field_value(rid,ARRAY['autorEmail']::varchar[]),epav_data.field_value(rid,ARRAY['criadoEm']::varchar[])::timestamptz,before_id,after_id)
    ON CONFLICT(id) DO UPDATE SET registro_id=excluded.registro_id,produto_origem_id=excluded.produto_origem_id,produto_atual_id=excluded.produto_atual_id,autor_uid=excluded.autor_uid,autor_email=excluded.autor_email,criado_em=excluded.criado_em,antes_versao_id=excluded.antes_versao_id,depois_versao_id=excluded.depois_versao_id;
  ELSIF r.collection_path='sincronizacao_imagens_swift' THEN
    SELECT id INTO current_id FROM epav_data.produtos_swift WHERE id=r.document_id;
    INSERT INTO epav_data.sincronizacao_imagens_swift(id,registro_id,produto_origem_id,produto_atual_id,verificado_em,etag,last_modified,pixel_hash,url_origem,status) VALUES(r.document_id,rid,r.document_id,current_id,epav_data.field_value(rid,ARRAY['checkedAt']::varchar[])::timestamptz,epav_data.field_value(rid,ARRAY['etag']::varchar[]),epav_data.field_value(rid,ARRAY['lastModified']::varchar[]),epav_data.field_value(rid,ARRAY['pixelHash']::varchar[]),epav_data.field_value(rid,ARRAY['sourceUrl']::varchar[]),epav_data.field_value(rid,ARRAY['status']::varchar[]))
    ON CONFLICT(id) DO UPDATE SET registro_id=excluded.registro_id,produto_origem_id=excluded.produto_origem_id,produto_atual_id=excluded.produto_atual_id,verificado_em=excluded.verificado_em,etag=excluded.etag,last_modified=excluded.last_modified,pixel_hash=excluded.pixel_hash,url_origem=excluded.url_origem,status=excluded.status;
  END IF;
END $$;

DO $$ DECLARE r record; BEGIN
  FOR r IN SELECT row_id FROM epav_data.records ORDER BY
    CASE collection_path WHEN 'importacoes_catalogo' THEN 0 WHEN 'produtos_swift' THEN 1
      WHEN 'arquivo_produtos_swift' THEN 2 WHEN 'auditoria_catalogo' THEN 3 ELSE 4 END,row_id
  LOOP PERFORM epav_data.refresh_business_record(r.row_id); END LOOP;
END $$;

CREATE FUNCTION epav_data.refresh_business_trigger() RETURNS trigger
LANGUAGE plpgsql SET search_path=pg_catalog,epav_data AS $$
BEGIN PERFORM epav_data.refresh_business_record(NEW.row_id); RETURN NULL; END $$;
CREATE CONSTRAINT TRIGGER business_record_sync AFTER INSERT OR UPDATE ON epav_data.records
  DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION epav_data.refresh_business_trigger();

DROP VIEW epav_data.products;
CREATE VIEW epav_data.products AS
SELECT p.id,p.nome,p.codigo,p.disponivel_no_jogo AS disponivel,p.tipos_produto AS tipos,p.ocasioes,
  i.url AS imagem_url,d.marca,d.formato,d.unidade_medida AS unidade
FROM epav_data.produtos_swift p LEFT JOIN epav_data.produtos_swift_imagens i ON i.produto_id=p.id
LEFT JOIN epav_data.produtos_swift_dados_originais d ON d.produto_id=p.id;

REVOKE ALL ON ALL TABLES IN SCHEMA epav_data FROM PUBLIC;
REVOKE ALL ON ALL FUNCTIONS IN SCHEMA epav_data FROM PUBLIC;
